def _promote(a, b):
    """Promote two numeric TsFile data types to a common wider type."""
    from tsfile import TSDataType

    if a == b:
        return a
    ints = {TSDataType.INT32, TSDataType.INT64}
    floats = {TSDataType.FLOAT, TSDataType.DOUBLE}
    if a in ints and b in ints:
        return TSDataType.INT64
    if a in floats and b in floats:
